public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        try {
            return doSearch(objectApiName, fields, filters, orderByField, maxRows);
        } catch (SearchException ex) {
            throw ex;
        } catch (Exception ex) {
            SearchException se = new SearchException();
            se.setMessage('Unexpected error: ' + ex.getMessage());
            throw se;
        }
    }

    private static List<SObject> doSearch(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throwException('maxRows must be between 1 and 200');
        }

        if (fields == null || fields.isEmpty()) {
            throwException('fields must not be null or empty');
        }

        if (String.isBlank(objectApiName)) {
            throwException('objectApiName must not be blank');
        }

        // --- Resolve object (case-insensitive) ---
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        String objLower = objectApiName.toLowerCase();
        Schema.SObjectType sObjType = null;
        for (String key : globalDescribe.keySet()) {
            if (key.toLowerCase() == objLower) {
                sObjType = globalDescribe.get(key);
                break;
            }
        }
        if (sObjType == null) {
            throwException('Object "' + objectApiName + '" does not exist');
        }

        Schema.DescribeSObjectResult sObjDesc = sObjType.getDescribe();
        if (!sObjDesc.isAccessible()) {
            throwException('Running user cannot read object "' + objectApiName + '"');
        }

        // --- Build case-insensitive field lookup ---
        Map<String, Schema.SObjectField> fieldMap = sObjDesc.fields.getMap();

        // --- Validate SELECT fields ---
        List<String> selectParts = new List<String> { 'Id' };
        Set<String> selectLower = new Set<String> { 'id' };

        for (String fieldName : fields) {
            if (String.isBlank(fieldName)) {
                continue;
            }
            String lower = fieldName.toLowerCase();
            if (selectLower.contains(lower)) {
                continue; // skip duplicates
            }

            if (!fieldMap.containsKey(lower)) {
                throwException('Field "' + fieldName + '" does not exist on object');
            }
            Schema.SObjectField fld = fieldMap.get(lower);
            if (!fld.getDescribe().isAccessible()) {
                throwException('Running user cannot read field "' + fieldName + '"');
            }
            selectParts.add(fieldName);
            selectLower.add(lower);
        }

        // --- Validate and build WHERE clause ---
        List<String> whereParts = new List<String>();
        if (filters != null && !filters.isEmpty()) {
            // First pass: validate all filter keys
            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) {
                    continue;
                }
                String lower = filterKey.toLowerCase();
                if (!fieldMap.containsKey(lower)) {
                    throwException('Filter field "' + filterKey + '" does not exist on object');
                }
                Schema.SObjectField fld = fieldMap.get(lower);
                if (!fld.getDescribe().isAccessible()) {
                    throwException('Running user cannot read filter field "' + filterKey + '"');
                }
                if (!fld.getDescribe().isFilterable()) {
                    throwException('Filter field "' + filterKey + '" cannot be used in a WHERE clause');
                }
            }

            // Second pass: build WHERE conditions
            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) {
                    continue;
                }
                Object val = filters.get(filterKey);
                String formattedVal = formatValue(val);
                whereParts.add(filterKey + ' = ' + formattedVal);
            }
        }

        // --- Validate ORDER BY field ---
        String orderClause = '';
        if (String.isNotBlank(orderByField)) {
            String lower = orderByField.toLowerCase();
            if (!fieldMap.containsKey(lower)) {
                throwException('Order-by field "' + orderByField + '" does not exist on object');
            }
            Schema.SObjectField fld = fieldMap.get(lower);
            if (!fld.getDescribe().isAccessible()) {
                throwException('Running user cannot read order-by field "' + orderByField + '"');
            }
            if (!fld.getDescribe().isSortable()) {
                throwException('Field "' + orderByField + '" cannot be used in an ORDER BY clause');
            }
            orderClause = ' ORDER BY ' + orderByField + ' ASC';
        }

        // --- Assemble and execute SOQL ---
        String soql = 'SELECT ' + String.join(selectParts, ', ')
                    + ' FROM ' + sObjDesc.getName();

        if (!whereParts.isEmpty()) {
            soql += ' WHERE ' + String.join(whereParts, ' AND ');
        }
        soql += orderClause;
        soql += ' LIMIT ' + String.valueOf(maxRows);

        return Database.query(soql);
    }

    // ---------------------------------------------------------------- helpers

    /**
     * Formats a filter value for safe inclusion in a SOQL WHERE clause.
     * String and Id values are single-quoted and quote-escaped to prevent SOQL injection.
     * Date and Datetime are formatted as SOQL literals.
     */
    private static String formatValue(Object val) {
        if (val == null) {
            return 'null';
        }
        if (val instanceof Boolean) {
            return (Boolean) val ? 'true' : 'false';
        }
        if (val instanceof Integer || val instanceof Long) {
            return String.valueOf(val);
        }
        if (val instanceof Decimal || val instanceof Double) {
            return String.valueOf(val);
        }
        if (val instanceof Date) {
            // String.valueOf(Date) produces yyyy-MM-dd, valid SOQL date literal
            return String.valueOf((Date) val);
        }
        if (val instanceof Datetime) {
            // String.valueOf(Datetime) produces yyyy-MM-dd HH:mm:ss (GMT)
            // SOQL needs yyyy-MM-dd'T'HH:mm:ss'Z'
            return String.valueOf((Datetime) val).replace(' ', 'T') + 'Z';
        }
        // Id – must be quoted in SOQL
        if (val instanceof Id) {
            return '\'' + String.escapeSingleQuotes(String.valueOf(val)) + '\'';
        }
        // String – must be quoted and escaped in SOQL
        if (val instanceof String) {
            return '\'' + String.escapeSingleQuotes((String) val) + '\'';
        }
        // Fallback – quote and escape
        return '\'' + String.escapeSingleQuotes(String.valueOf(val)) + '\'';
    }

    private static void throwException(String msg) {
        SearchException se = new SearchException();
        se.setMessage(msg);
        throw se;
    }
}
