public with sharing class ContactLookupAction {

    @InvocableMethod(label='Find Contact by Email', description='Finds a Contact by email address, case-insensitive and trimmed', supportsPagination=true)
    public static List<Result> find(List<Request> requests) {

        if (requests == null || requests.isEmpty()) {
            return new List<Result>();
        }

        // 1. Normalise every request email to a trimmed-lowercase key
        List<String> keys = new List<String>(requests.size());
        Set<String> searchKeys = new Set<String>();

        for (Request req : requests) {
            if (req == null || String.isBlank(req.email)) {
                keys.add(null);
            } else {
                String key = req.email.trim().toLowerCase();
                keys.add(key);
                searchKeys.add(key);
            }
        }

        // 2. Single bulk SOQL - one round-trip regardless of batch size
        List<Contact> contacts = searchKeys.isEmpty()
            ? new List<Contact>()
            : [SELECT Id, Email, CreatedDate
               FROM Contact
               WHERE Email IN :searchKeys
               ORDER BY CreatedDate ASC];

        // 3. Build a lookup keyed on normalised email -> earliest Contact Id.
        //    Because the query is ordered by CreatedDate ASC the first entry
        //    we encounter for a key is always the one with the earliest CreatedDate.
        Map<String, Id> earliestIdByNormalisedEmail = new Map<String, Id>();
        for (Contact c : contacts) {
            if (c.Email == null) continue;
            String cKey = c.Email.trim().toLowerCase();
            if (!earliestIdByNormalisedEmail.containsKey(cKey)) {
                earliestIdByNormalisedEmail.put(cKey, c.Id);
            }
        }

        // 4. Build one Result per Request, in the same order
        List<Result> results = new List<Result>();
        for (Integer i = 0; i < requests.size(); i++) {
            Result r = new Result();
            String key = keys[i];

            if (key != null && earliestIdByNormalisedEmail.containsKey(key)) {
                r.found = true;
                r.contactId = earliestIdByNormalisedEmail.get(key);
            } else {
                r.found = false;
                r.contactId = null;
            }

            results.add(r);
        }

        return results;
    }

    // -- Invocable input wrapper --

    public class Request {
        @InvocableVariable(label='Email', required=true)
        public String email;
    }

    // -- Invocable output wrapper --

    public class Result {
        @InvocableVariable(label='Contact Id')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }
}
