@IsTest
private class OpportunityWonHandlerTest {

    @IsTest
    static void testInsertClosedWon_WithNonHotAccount_ExpectFullHandover() {
        Account acc = new Account(Name = 'HotTest Acct', Rating = 'Warm');
        insert acc;

        Test.startTest();
        Date closeDate = Date.today().addDays(14);
        Opportunity opp = new Opportunity(
            Name = 'Won Opp',
            StageName = 'Closed Won',
            CloseDate = closeDate,
            Amount = 10000,
            AccountId = acc.Id
        );
        insert opp;
        Test.stopTest();

        // Re-query to get all needed fields
        Opportunity oppAfter = [SELECT Id, NextStep, OwnerId FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals('Handover to Customer Success', oppAfter.NextStep,
            'NextStep must be set for a newly won insert');

        // Verify Task created by afterInsert
        List<Task> tasks = [SELECT Subject, WhatId, OwnerId, ActivityDate, Priority FROM Task WHERE WhatId = :opp.Id];
        System.assertEquals(1, tasks.size(), 'Exactly one task per newly won opp');
        Task t = tasks[0];
        System.assertEquals('Customer kick-off', t.Subject, 'Wrong Task Subject');
        System.assertEquals(opp.Id, t.WhatId, 'Wrong Task WhatId');
        System.assertEquals(oppAfter.OwnerId, t.OwnerId, 'Wrong Task OwnerId');
        System.assertEquals('High', t.Priority, 'Wrong Task Priority');
        System.assertEquals(closeDate.addDays(7), t.ActivityDate, 'Wrong Task ActivityDate');

        // Verify Account Rating updated to Hot
        Account accAfter = [SELECT Rating FROM Account WHERE Id = :acc.Id];
        System.assertEquals('Hot', accAfter.Rating, 'Account Rating should become Hot');
    }

    @IsTest
    static void testInsertClosedWon_WithoutAccount_ExpectTaskButNoAccountUpdate() {
        Test.startTest();
        Opportunity opp = new Opportunity(
            Name = 'Won Opp No Acct',
            StageName = 'Closed Won',
            CloseDate = Date.today(),
            Amount = 5000
        );
        insert opp;
        Test.stopTest();

        Opportunity oppAfter = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals('Handover to Customer Success', oppAfter.NextStep);

        List<Task> tasks = [SELECT Id, Subject FROM Task WHERE WhatId = :opp.Id];
        System.assertEquals(1, tasks.size(), 'Task should be created even without an account');
        System.assertEquals('Customer kick-off', tasks[0].Subject);
    }

    @IsTest
    static void testInsertNonWon_ExpectNoAction() {
        Account acc = new Account(Name = 'NoAcctChange', Rating = 'Warm');
        insert acc;

        Test.startTest();
        Opportunity opp = new Opportunity(
            Name = 'Prospecting Opp',
            StageName = 'Prospecting',
            CloseDate = Date.today(),
            Amount = 5000,
            AccountId = acc.Id
        );
        insert opp;
        Test.stopTest();

        List<Task> tasks = [SELECT Id FROM Task WHERE WhatId = :opp.Id];
        System.assertEquals(0, tasks.size(), 'No task should be created for non-won insert');

        Opportunity oppAfter = [SELECT NextStep FROM Opportunity WHERE Id = :opp.Id];
        System.assertNotEquals('Handover to Customer Success', oppAfter.NextStep,
            'NextStep must not be set for non-won insert');

        Account accAfter = [SELECT Rating FROM Account WHERE Id = :acc.Id];
        System.assertEquals('Warm', accAfter.Rating, 'Account Rating must not change for non-won opp');
    }

    @IsTest
    static void testUpdateToClosedWon_ExpectFullHandover() {
        Account acc = new Account(Name = 'UpdateTest Acct', Rating = 'Warm');
        insert acc;

        Opportunity opp = new Opportunity(
            Name = 'Moving to Won',
            StageName = 'Prospecting',
            CloseDate = Date.today().addDays(5),
            Amount = 10000,
            AccountId = acc.Id
        );
        insert opp;

        Test.startTest();
        opp = [SELECT Id, StageName, CloseDate, AccountId, OwnerId FROM Opportunity WHERE Id = :opp.Id];
        opp.StageName = 'Closed Won';
        update opp;
        Test.stopTest();

        // Verify NextStep (beforeUpdate context)
        Opportunity oppAfter = [SELECT Id, NextStep, OwnerId FROM Opportunity WHERE Id = :opp.Id];
        System.assertEquals('Handover to Customer Success', oppAfter.NextStep,
            'NextStep must be set when updated to Won');

        // Verify Task (afterUpdate context)
        List<Task> tasks = [SELECT Subject, WhatId, OwnerId, ActivityDate, Priority FROM Task WHERE WhatId = :opp.Id];
        System.assertEquals(1, tasks.size(), 'Task should be created on update to Won');
