public with sharing class AccountsSelector extends fflib_SObjectSelector {

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        Map<String, Schema.SObjectField> fields = new Map<String, Schema.SObjectField>();
        fields.put('Id', Account.Id);
        fields.put('Name', Account.Name);
        fields.put('Industry', Account.Industry);

        Map<String, Schema.FieldSet> fsMap =
            Schema.SObjectType.Account.getDescribe().fieldSets.getMap();
        Schema.FieldSet fs = fsMap.get('Credit_Review');
        if (fs != null) {
            Map<String, Schema.SObjectField> fldMap =
                Schema.SObjectType.Account.getDescribe().fields.getMap();
            for (Schema.FieldSetMember fsm : fs.getDisplayedFields()) {
                Schema.SObjectField f = fldMap.get(fsm.getFieldPath());
                if (f != null) {
                    fields.put(fsm.getFieldPath(), f);
                }
            }
        }

        return fields.values();
    }

    protected override System.SecurityMode getDataAccessLevel() {
        return System.SecurityMode.User_Mode;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        List<String> fieldNames = buildFieldNames(getSObjectFieldList());
        String query = String.join(fieldNames, ', ');
        query = 'SELECT ' + query +
                ' FROM Account WHERE Id IN :accountIds WITH USER_MODE';
        return (List<Account>) Database.query(query);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        List<String> acctFieldNames = buildFieldNames(getSObjectFieldList());

        ContactsSelector contactsSelector = new ContactsSelector();
        List<String> contFieldNames = buildFieldNames(contactsSelector.getSObjectFieldList());

        String query = 'SELECT ' + String.join(acctFieldNames, ', ') +
                       ', (SELECT ' + String.join(contFieldNames, ', ') +
                       ' FROM Contacts)' +
                       ' FROM Account WHERE Id IN :accountIds WITH USER_MODE';

        return (List<Account>) Database.query(query);
    }

    private List<String> buildFieldNames(List<Schema.SObjectField> fields) {
        List<String> names = new List<String>();
        for (Schema.SObjectField f : fields) {
            names.add(f.getDescribe().getName());
        }
        return names;
    }
