 *
 * Purpose
 *   When a Case transitions Open → Closed and has a Contact, create a
 *   CSAT survey Task asynchronously so the closing DML is never blocked
 *   by survey work (and so a single Task failure can't roll back others).
 *
 * Queueable enqueue limit (50 System.enqueueJob calls per transaction)
 *   • List-view bulk closes and small API batches (≤ 50 cases in one
 *     DML) work as-is.
 *   • The 200-case nightly cleanup MUST be chunked into API batches of
 *     ≤ 50 records (e.g. Apex Bulk API batch size 50), or wrapped in a
 *     BatchApex class that fans-out enqueues across batch scopes.
 *   A single transaction with > 50 qualifying cases will hit the
 *   governor limit and roll back the entire DML – that is a caller /
 *   integration concern, not a trigger-logic defect.
 */
trigger CaseTrigger on Case (after update) {

    if (!Trigger.isAfter || !Trigger.isUpdate) {
        return;
    }

    for (Case newCase : Trigger.new) {

        Case oldCase = Trigger.oldMap.get(newCase.Id);

        // Only act on the Open → Closed transition
        if (!newCase.IsClosed || oldCase.IsClosed) {
            continue;
        }

        // No Contact → no survey possible
        if (newCase.ContactId == null) {
            continue;
        }

        // One Queueable per case → maximum blast-radius isolation
        System.enqueueJob(new CaseSurveyJob(newCase.Id));
    }
}
