/**
 * CaseSurveyJob
 *
 * Queueable class enqueued by CaseTrigger after a Case is closed.
 *
 * Runs in its own asynchronous transaction, so a Task-insert failure
 * here affects only this one case and leaves the other 199 surveys
 * (if any) in their own independent Queueable jobs untouched.
 *
 * We re-query the Case inside execute() because by the time the
 * queue fires the parent transaction has already committed and the
 * Case's ContactId could have changed (e.g. case re-assignment).
 */
public with sharing class CaseSurveyJob implements System.Queueable {

    private final Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    /**
     * @param context  System.QueueableContext – execution context handle.
     *                 Not used here (one job = one case, no chaining).
     */
    public void execute(System.QueueableContext context) {

        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM   Case
            WHERE  Id = :caseId
            LIMIT  1
        ];

        if (cases.isEmpty()) {
            // Case was hard-deleted between enqueue and execution
            return;
        }

        Case c = cases[0];

        // Defensive re-check – case state may have changed since enqueue
        if (!c.IsClosed || c.ContactId == null) {
            return;
        }

        Task surveyTask = new Task();
        surveyTask.WhatId       = c.Id;
        surveyTask.WhoId        = c.ContactId;
        surveyTask.Subject      = 'CSAT survey: ' + c.CaseNumber;
        surveyTask.ActivityDate = Date.today().addDays(2);
        surveyTask.Status       = 'Not Started';

        insert surveyTask;
    }
}
