public with sharing class RenewalReminderService {

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Bulk-safe SOQL – never inside a loop
        List<Opportunity> opps = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM   Opportunity
            WHERE  Id IN :opportunityIds
            LIMIT  200
        ];

        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : opps) {
            // Only User records (Id prefix 005…) are valid targets for
            // setTargetObjectId; skip Queue / Team-managed records.
            if (opp.OwnerId == null ||
                !String.valueOf(opp.OwnerId).startsWith('005')) {
                continue;
            }

            Messaging.SingleEmailMessage msg = new Messaging.SingleEmailMessage();
            msg.setTargetObjectId(opp.OwnerId);
            msg.setSaveAsActivity(false);
            msg.setSubject('Renewal due: ' + opp.Name);
            msg.setPlainTextBody(
                'Hello,\\n\\nA renewal is due for opportunity "' + opp.Name
                + '".\\n\\n  Close date : ' + opp.CloseDate
                + '\\n\\nPlease review and take any necessary action before the close date.\\n\\n-- Renewal Reminder Bot'
            );

            messages.add(msg);
        }

        if (messages.isEmpty()) {
            return 0;
        }

        // Single sendEmail invocation respects the 10-invocation governor limit
        // while still providing per-message fault isolation via isSuccess().
        Messaging.SendEmailResult[] results =
            Messaging.sendEmail(messages, false);

        Integer successCount = 0;
        for (Messaging.SendEmailResult r : results) {
            if (r.isSuccess()) {
                successCount++;
            }
        }

        return successCount;
    }
}
