import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading = '';

    @api
    get heading() {
        return this._heading;
    }
    set heading(value) {
        this._heading = value;
    }

    get displayHeading() {
        return this._heading ? this._heading.toUpperCase() : this._heading;
    }

    _tasks = [];

    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = Array.isArray(value) ? value.map((t) => ({ ...t })) : [];
    }

    newLabel = '';
    nextId = 1;

    get remaining() {
        return this._tasks.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = this.newLabel ? this.newLabel.trim() : '';
        if (!label) {
            return;
        }
        this._tasks = [
            ...this._tasks,
            { id: `new-${this.nextId++}`, label, done: false }
        ];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this._tasks = this._tasks.map((task) =>
            task.id === id ? { ...task, done: !task.done } : task
        );
    }
}
