/**
 * Stages website gifts as NPSP Data Import (BDI) records and processes them
 * synchronously in the same transaction using NPSP's Apex BDI API so that
 * NPSP contact-matching, household-creation and donation-processing rules apply.
 *
 * Usage from an integration handler:
 *   List<ImportResult> results = GiftImportService.importGifts(giftList);
 */
public with sharing class GiftImportService {

    // ── Inner DTOs ──────────────────────────────────────────────────────
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;      // donor personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;         // matched / created Contact
        public Id opportunityId;     // created Opportunity (donation)
        public String errorMessage;  // NPSP failure detail when success == false
    }

    // ── Public entry point ──────────────────────────────────────────────
    /**
     * @param gifts  up to 200 gifts; null/empty → empty result list
     * @return one ImportResult per gift, in input order
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {

        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // 1. Stage one Data Import record per gift ──────────────────────
        List<npsp__DataImport__c> diList = new List<npsp__DataImport__c>(gifts.size());

        for (WebGift g : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c       = g.firstName;
            di.npsp__Contact1_Lastname__c        = g.lastName;
            di.npsp__Contact1_Personal_Email__c = g.email;
            di.npsp__Donation_Amount__c           = g.amount;
            di.npsp__Donation_Date__c             = g.giftDate;
            di.npsp__Donation_Donor__c            = 'Contact1';
            diList.add(di);
        }

        insert diList;

        // 2. Process synchronously via NPSP BDI (Batch Data Import) API ─
        //    NPSP applies the org's Data Import Settings (matching rules,
        //    household auto-creation, etc.) and updates Status,
        //    Contact1Imported, DonationImported, FailureInformation on
        //    each record.  Per-record failures are marked Failed without
        //    aborting the batch.
        npsp.BDI.handleDataImport(diList);

        // 3. Re-query to obtain the processed field values ──────────────
        //    (handleDataImport may have changed fields in-memory and via
        //     internal DML; a fresh query guarantees we see the persisted
        //     state and avoids "field was not loaded" exceptions.)
        List<npsp__DataImport__c> processedList = [
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
              FROM npsp__DataImport__c
             WHERE Id IN :diList
        ];

        // Index by Id so we can walk the original gift order.
        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>();
        for (npsp__DataImport__c di : processedList) {
            processedById.put(di.Id, di);
        }

        // 4. Build one ImportResult per gift, in input order ────────────
        List<ImportResult> results = new List<ImportResult>(gifts.size());

        for (Integer i = 0; i < diList.size(); i++) {
            npsp__DataImport__c di = diList[i];       // Id populated by insert
            npsp__DataImport__c processed = processedById.get(di.Id);

            ImportResult r = new ImportResult();

            if (processed != null) {
                r.success      = (processed.npsp__Status__c == 'Imported');
                r.contactId    = processed.npsp__Contact1Imported__c;
                r.opportunityId = processed.npsp__DonationImported__c;
                r.errorMessage = (r.success)
                    ? null
                    : (String.isBlank(processed.npsp__FailureInformation__c)
                        ? 'Unknown import failure'
                        : processed.npsp__FailureInformation__c);
            } else {
                // Safety net – should never happen with synchronous BDI,
                // but guards against unexpected DML rollback.
                r.success      = false;
                r.errorMessage = 'Data Import record not found after processing';
            }

            results.add(r);
        }

        return results;
    }
}
