```apex
/**
 * Bulk-safe service that creates NPSP parent–child Relationships.
 *
 * For each child→parent pair we create exactly ONE Relationship record
 * (Child → Parent, Type "Parent").  NPSP's trigger then auto-creates the
 * reciprocal record (Parent → Child with the correct Type from the
 * Relationship Lookup: Son / Daughter / Child) and links the two via
 * npe4__ReciprocalRelationship__c.  We must NOT pre-link or create the
 * reciprocal ourselves or NPSP will produce duplicates.
 *
 * Governor-budget (per call, regardless of input size):
 *   1  SOQL  npe4__Relationship__c   (existing-pair dedup guard)
 *   1  DML   insert                  (all new records in one statement)
 */
public with sharing class FamilyService {

    private static final String TYPE_PARENT    = 'Parent';
    private static final String STATUS_CURRENT = 'Current';

    /**
     * For every child→parent pair in <em>parentIdByChildId</em>, create a
     * single Child→Parent Relationship (Type "Parent", Status "Current").
     * Pairs where any Relationship already exists between the two Contacts
     * (in either direction) are skipped so the import is idempotent.
     *
     * @param parentIdByChildId  child Contact Id → parent Contact Id
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {

        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // ── Collect every unique Contact Id ───────────────────────────
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            allContactIds.add(childId);
            Id parentId = parentIdByChildId.get(childId);
            if (parentId != null) {
                allContactIds.add(parentId);
            }
        }

        if (allContactIds.isEmpty()) {
            return;
        }

        // ── SOQL (1 query) – find every existing Relationship that
        //    involves ANY of the Contacts we are about to touch, in
        //    EITHER direction.  This is the dedup guard. ────────────────
        Set<String> existingPairKeys = new Set<String>();

        for (npe4__Relationship__c rel : [
                SELECT npe4__Contact__c, npe4__RelatedContact__c
                FROM   npe4__Relationship__c
                WHERE  npe4__Contact__c          IN :allContactIds
                  AND  npe4__RelatedContact__c   IN :allContactIds
              ]) {

            Id c1 = rel.npe4__Contact__c;
            Id c2 = rel.npe4__RelatedContact__c;

            if (c1 == null || c2 == null) {
                continue;
            }

            // Canonical pair key – order-independent so both directions
            // of an existing pair collapse to the same key.
            String pairKey = (c1 < c2) ? (c1 + ':' + c2) : (c2 + ':' + c1);
            existingPairKeys.add(pairKey);
        }

        // ── Build the new Relationship records ────────────────────────
        //    ONE record per pair; NPSP's trigger auto-creates the
        //    reciprocal and sets npe4__ReciprocalRelationship__c.
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {

            Id parentId = parentIdByChildId.get(childId);

            // Skip null parent or self-reference
            if (parentId == null || childId == parentId) {
                continue;
            }

            // Canonical pair key for this child↔parent pair
            String pairKey = (childId < parentId)
                                 ? (childId + ':' + parentId)
                                 : (parentId + ':' + childId);

            // Skip if any Relationship already exists between the two
            if (existingPairKeys.contains(pairKey)) {
                continue;
            }

            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c        = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c           = TYPE_PARENT,
                npe4__Status__c         = STATUS_CURRENT
            ));

            // Mark the pair as handled so a second iteration that touches
            // the same two Contacts (e.g. A→B and B→A in the input map)
            // is also skipped.
            existingPairKeys.add(pairKey);
        }

        // ── DML (1 statement) ─────────────────────────────────────────
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
