```java
public with sharing class RecordAccessService {

    public static Set<Id> editableIds(Set<Id> recordIds) {
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        Set<Id> editable = new Set<Id>();

        // UserRecordAccess enforces a 200-row-per-query SOQL limit.
        // Batch the IN list into chunks of 200 so each query stays within that cap.
        // 2 000 / 200 = 10 queries, well under the 20-query budget.
        final Integer BATCH_SIZE = 200;

        List<Id> idList = new List<Id>(recordIds);
        for (Integer i = 0; i < idList.size(); i += BATCH_SIZE) {
            Integer end = Math.min(i + BATCH_SIZE, idList.size());

            // Build a bounded sub-set for this chunk
            Set<Id> batch = new Set<Id>();
            for (Integer j = i; j < end; j++) {
                batch.add(idList[j]);
            }

            // Only SELECT RecordId (no extra fields) so we CAN filter on HasEditAccess
            // (Salesforce restricts filtering on Has*Access when a second SELECT field
            //  is present – selecting RecordId alone avoids that restriction).
            List<UserRecordAccess> accesses = [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND RecordId IN :batch
                  AND HasEditAccess = true
            ];

            for (UserRecordAccess ura : accesses) {
                editable.add(ura.RecordId);
            }
        }

        return editable;
    }
}
